package com.learnagent.digest;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/daily-digests")public class DailyDigestController{private final DailyDigestService service;public DailyDigestController(DailyDigestService service){this.service=service;}@PostMapping("/generate")public ResponseEntity<DailyDigestService.DigestView>generate(){return ResponseEntity.status(HttpStatus.CREATED).body(service.generateToday());}@GetMapping("/latest")public ResponseEntity<DailyDigestService.DigestView>latest(){var value=service.latest();return value==null?ResponseEntity.noContent().build():ResponseEntity.ok(value);}@GetMapping public List<DailyDigestService.DigestView>list(){return service.list();}}
